package dev.infend.skyrimtext;
import org.junit.Test;
import static org.junit.Assert.*;
public class RoadRewardMechanicsTest {
    GameEngine hero(){GameEngine g=new GameEngine();g.start("Герой","Норд","Воин");g.hp=g.maxHp=500;g.magicka=g.maxMagicka=100;g.mode="WORLD";return g;}
    @Test public void necklaceChangesCapacityOnlyWhileEquipped() throws Exception {GameEngine g=hero();assertEquals(50,g.progress.carryLimit(),0.01);assertTrue(g.progress.addItem("Зачарованное ожерелье",1));assertTrue(g.progress.equip("Зачарованное ожерелье"));assertEquals(75,g.progress.carryLimit(),0.01);g=GameEngine.fromJson(g.toJson().toString());assertEquals(75,g.progress.carryLimit(),0.01);g.progress.unequip("Зачарованное ожерелье");assertEquals(50,g.progress.carryLimit(),0.01);}
    @Test public void staffSummonRequiresEquippedItemAndPersists() throws Exception {GameEngine g=hero();assertTrue(g.progress.addItem("Роза Сангвина",1));assertTrue(g.progress.equip("Роза Сангвина"));g.beginRoadBattle("Маг",200,1,"");g.choose("ROAD_SUMMON_ROSE");assertEquals(2,g.roadSummonTurns);assertEquals(1,g.roadSummonKind);assertTrue(g.enemyHp<200);g=GameEngine.fromJson(g.toJson().toString());assertEquals(2,g.roadSummonTurns);g.choose("DEFEND");assertEquals(1,g.roadSummonTurns);g.choose("DEFEND");assertEquals(0,g.roadSummonTurns);}
    @Test public void spellbreakerIsARealShield(){GameEngine g=hero();assertEquals("shield",ItemCatalog.find("Разрушитель Заклинаний").slot());assertTrue(g.progress.addItem("Разрушитель Заклинаний",1));assertTrue(g.progress.equip("Разрушитель Заклинаний"));}
    @Test public void estatesRequirePurchase() throws Exception {GameEngine g=hero();g.gold=6000;g.progress.location="Фолкрит";assertFalse(RoadEvents.availableAt(g,"home_bandits",5));g.choose("ROADESTATE:5");assertEquals(1000,g.gold);assertTrue(RoadEvents.availableAt(g,"home_bandits",5));g=GameEngine.fromJson(g.toJson().toString());g.choose("ROADESTATE:5");assertEquals(1000,g.gold);assertTrue(RoadEvents.ownsEstate(g,5));}
    @Test public void giftRequiresRememberedBenefactor(){GameEngine g=hero();g.reputation=10;assertFalse(RoadEvents.availableAt(g,"friend_gift",0));g.progress.setQuestOutcome("road_friend_bitten_hunter","ACTIVE");assertTrue(RoadEvents.availableAt(g,"friend_gift",0));g.mode="ROAD";g.road.id="friend_gift";g.road.destination="Ривервуд";int gold=g.gold;for(GameEngine.Choice c:g.scene().choices)if(c.action.endsWith(":gift")){g.choose(c.action);break;}assertEquals(gold+10,g.gold);assertFalse(RoadEvents.availableAt(g,"friend_gift",0));}
}
